package com.nextfeet.nextfeet.controller; import jakarta.servlet.http.*; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import com.nextfeet.nextfeet.model.Usuario; import com.nextfeet.nextfeet.cart.CarritoService; @Controller @RequestMapping("/carrito") public class CarritoController {private final CarritoService s; public CarritoController(CarritoService s){this.s=s;} private Integer u(HttpSession h){Usuario usuario=(Usuario)h.getAttribute("usuario");return usuario==null?null:usuario.getId();} @GetMapping public String ver(HttpSession h,Model m){if(u(h)==null)return "redirect:/login";m.addAttribute("items",s.listar(u(h)));m.addAttribute("total",s.total(u(h)));return "cliente/carrito";} @GetMapping("/panel") public String panel(HttpSession h,Model m,jakarta.servlet.http.HttpServletResponse response){if(u(h)==null){response.setStatus(401);return "cliente/carrito-panel";}m.addAttribute("items",s.listar(u(h)));m.addAttribute("total",s.total(u(h)));return "cliente/carrito-panel";} @PostMapping("/agregar") public String agregar(@RequestParam Integer zapatillaId,@RequestParam String talla,@RequestParam(defaultValue="1")int cantidad,HttpSession h){if(u(h)==null)return "redirect:/login";s.agregar(u(h),zapatillaId,talla,cantidad);return "redirect:/carrito";} @PostMapping("/actualizar") public String actualizar(@RequestParam Integer zapatillaId,@RequestParam String talla,@RequestParam int cantidad,HttpSession h){if(u(h)==null)return "redirect:/login";s.actualizar(u(h),zapatillaId,talla,cantidad);return "redirect:/carrito";} @PostMapping("/eliminar") public String eliminar(@RequestParam Integer zapatillaId,@RequestParam String talla,HttpSession h){if(u(h)==null)return "redirect:/login";s.eliminar(u(h),zapatillaId,talla);return "redirect:/carrito";} @PostMapping("/vaciar") public String vaciar(HttpSession h){if(u(h)==null)return "redirect:/login";s.vaciar(u(h));return "redirect:/carrito";} }